SELECT column_name, data_type
  FROM user_tab_columns
 WHERE table_name = 'EMPLOYEES';

steps.solution:
SELECT emp_id,
       SUBSTR(first_name, 1, 1) AS first_letter
  FROM employees;

SELECT emp_id, first_name, last_name, hire_date
  FROM employees
 WHERE EXTRACT(MONTH FROM hire_date) = EXTRACT(MONTH FROM SYSDATE);

SELECT prod_name,
       TO_CHAR(price, 'FM999,990.00') AS price_txt
  FROM products;

SELECT cust_name,
       COALESCE(email, city) AS contact
  FROM customers;
